def picture(root: str, name: str, alt: str) -> str:
    return f'''<figure class="media article-inline-image"><picture><source type="image/webp" srcset="{root}/{name}-640.webp 640w, {root}/{name}-960.webp 960w, {root}/{name}.webp 1536w" sizes="(max-width: 760px) calc(100vw - 2rem), 760px"><img src="{root}/{name}.jpg" width="1536" height="1024" loading="lazy" decoding="async" alt="{html.escape(alt)}"></picture></figure>'''


def schemas(article: dict, words: int) -> tuple[dict, dict]:
    canonical = f'https://byforo.com{article["url"]}'
    image = f'https://byforo.com{article["image"]["fallback"]}'
    article_schema = {
        "@context": "https://schema.org",
        "@type": "BlogPosting",
        "mainEntityOfPage": {"@type": "WebPage", "@id": canonical},
        "headline": article["title"],
        "description": article["metaDescription"],
        "image": [image],
        "datePublished": PUBLISHED_ISO,
        "dateModified": PUBLISHED_ISO,
        "author": {"@type": "Organization", "name": "by.foro Editorial", "url": "https://byforo.com/about/"},
        "publisher": {"@type": "Organization", "name": "by.foro", "url": "https://byforo.com/"},
        "articleSection": article["articleSection"],
        "keywords": article["keywords"],
        "inLanguage": "en-GB",
        "isAccessibleForFree": True,
        "wordCount": words,
    }
    department = article["department"]
    topic_label = article["articleSection"]
    crumbs = {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": "https://byforo.com/"},
            {"@type": "ListItem", "position": 2, "name": department.title(), "item": f"https://byforo.com/{department}/"},
            {"@type": "ListItem", "position": 3, "name": topic_label, "item": f'https://byforo.com/journal/?department={department}&topic={article["topic"]}'},
            {"@type": "ListItem", "position": 4, "name": article["title"], "item": canonical},
        ],
    }
    return article_schema, crumbs


