    header = f'''<!DOCTYPE html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f2eee7"><meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"><title>{html.escape(article["seoTitle"])}</title><meta name="description" content="{html.escape(article["metaDescription"])}"><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/icons/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><meta property="og:type" content="article"><meta property="og:locale" content="en_GB"><meta property="og:site_name" content="by.foro"><meta property="og:title" content="{html.escape(article["seoTitle"])}"><meta property="og:description" content="{html.escape(article["metaDescription"])}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://byforo.com{article["image"]["fallback"]}"><meta property="og:image:alt" content="{html.escape(article["image"]["alt"])}"><meta property="og:image:width" content="1536"><meta property="og:image:height" content="1024"><meta property="og:image:type" content="image/jpeg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(article["seoTitle"])}"><meta name="twitter:description" content="{html.escape(article["metaDescription"])}"><meta name="twitter:image" content="https://byforo.com{article["image"]["fallback"]}"><meta property="article:section" content="{html.escape(article["articleSection"])}"><meta property="article:published_time" content="{PUBLISHED_ISO}"><meta property="article:modified_time" content="{PUBLISHED_ISO}"><meta name="author" content="by.foro Editorial"><link rel="preload" as="style" href="/styles.css"><link rel="stylesheet" href="/styles.css"><link rel="alternate" type="application/rss+xml" title="by.foro Journal" href="https://byforo.com/rss.xml"><script id="article-schema" type="application/ld+json">{json.dumps(article_schema, ensure_ascii=False, separators=(',', ':'))}</script><script id="article-breadcrumb-schema" type="application/ld+json">{json.dumps(crumb_schema, ensure_ascii=False, separators=(',', ':'))}</script></head><body><a class="skip-link" href="#main">Skip to content</a>{site_header(article["url"])}'''
