def write_feature(article: dict, deck: str, toc: list[tuple[str, str]], body: str, words: int) -> None:
    destination = ROOT / article["url"].strip("/") / "index.html"
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(page(article, deck, toc, body, words), encoding="utf-8", newline="\n")
    print(f"Built {destination.relative_to(ROOT)}")


def update_catalogue() -> None:
    path = ROOT / "content" / "articles.json"
    articles = json.loads(path.read_text(encoding="utf-8"))
    new_articles = []
    for article, _, _, _, _ in FEATURES:
        record = {key: value for key, value in article.items() if key != "keywords"}
        new_articles.append(record)
    urls = {article["url"] for article in new_articles}
    articles = new_articles + [article for article in articles if article["url"] not in urls]
    path.write_text(json.dumps(articles, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")


def main() -> None:
    for feature in FEATURES:
        write_feature(*feature)
    update_catalogue()


if __name__ == "__main__":
    main()
